(n, m) = map(int, input().split())
adj = [0 for _ in range(n)]
p = [i for i in range(n)]
sz = [1 for i in range(n)]

def find(i):
	if i != p[i]:
		p[i] = find(p[i])
	return p[i]

def union(i, j):
	i = find(i)
	j = find(j)
	if sz[i] > sz[j]:
		sz[i] += sz[j]
		p[j] = i
	else:
		sz[j] += sz[i]
		p[i] = j
for _ in range(m):
	(a, b) = map(int, input().split())
	a -= 1
	b -= 1
	adj[a] += 1
	adj[b] += 1
	if find(a) != find(b):
		union(a, b)
l = set()
for i in range(n):
	l.add(find(i))
for i in range(n):
	if adj[i] != 2:
		if find(i) in l:
			l.remove(find(i))
print(len(l))
